import Foundation

/// Builds a unified `DailyReport` by aggregating data from all existing
/// sources: retrospective highlights/todos, pending asks, commitments,
/// reply debt, and recalled messages. Pure data assembly — no AI.
///
/// Designed to be called on the main actor (it reads `@MainActor` state
/// like `replyDebtItems`), but the builder itself is not isolated so it
/// can be used from background contexts when given a captured store.
struct DailyReportBuilder {
    let store: HUDStore
    let replyDebtItems: [ReplyDebtItem]
    let stats: HUDStats

    /// Builds a report for the current day (00:00 to now).
    /// If no retrospective run exists for today, degrades gracefully
    /// to asks + commitments + reply debt only.
    func build() -> DailyReport {
        let now = Date()
        let calendar = Calendar.current
        let startOfDay = calendar.startOfDay(for: now)
        let dateRange = (start: startOfDay, end: now)

        // 1. Retrospective data (latest run, may be from earlier today or before)
        let latestRun = store.latestCompletedRun()
        let runHighlights: [ReviewHighlight] = latestRun.map { store.highlights(for: $0.id) } ?? []
        let runTodos: [ReviewTodo] = latestRun.map { store.todos(for: $0.id, statuses: [.pending]) } ?? []

        // 2. Pending asks (today's scope)
        let pendingAsks = store.loadPendingAsks(status: .pending)
            .filter { $0.createdAt >= startOfDay }
        let handledAsks = store.loadPendingAsks(status: .done)
            .filter { $0.updatedAt >= startOfDay }

        // 3. Commitments
        let allCommitments = store.loadCommitments()
        let pendingCommitments = allCommitments.filter { $0.status == .pending }
        let overdueCommitments = allCommitments.filter { $0.status == .overdue }

        // 4. Recalled messages (today)
        let todayRecalled = store.loadRecalledMessages(since: Int(startOfDay.timeIntervalSince1970), limit: 50)
            .filter { $0.recalledAt >= Int(startOfDay.timeIntervalSince1970) }

        // 5. Build metrics
        let metrics = DailyReportMetrics(
            unreadMessageCount: stats.unreadCount,
            pendingTodoCount: runTodos.count,
            pendingAskCount: pendingAsks.count,
            pendingCommitmentCount: pendingCommitments.count,
            overdueCommitmentCount: overdueCommitments.count,
            replyDebtCount: replyDebtItems.count,
            recalledMessageCount: todayRecalled.count,
            highlightCount: runHighlights.count,
            analyzedChatCount: latestRun?.progressChatCount ?? 0
        )

        // 6. Build highlights (from retrospective)
        let highlights = runHighlights.map { h in
            DailyReportHighlight(
                summary: h.summary,
                category: h.category,
                sourceChatName: h.sourceChatName,
                sourceChatUsername: h.sourceChatUsername,
                date: h.date,
                confidence: h.confidence,
                quotedSnippet: h.quotedSnippet,
                involved: h.involved
            )
        }

        // 7. Build unified actions
        var actions: [DailyReportAction] = []

        // Todos from retrospective
        for todo in runTodos {
            actions.append(DailyReportAction(
                content: todo.content,
                type: .todo,
                urgency: urgencyFor(deadline: todo.deadline),
                deadline: todo.deadline,
                sourceChatName: todo.sourceChatName,
                sourceChatUsername: todo.sourceChatUsername,
                relatedID: "\(todo.id)"
            ))
        }

        // Commitments (pending + overdue)
        for c in pendingCommitments + overdueCommitments {
            actions.append(DailyReportAction(
                content: c.content,
                type: .commitment,
                urgency: urgencyFor(deadline: c.deadlineAt, status: c.status),
                deadline: c.deadlineAt,
                sourceChatName: c.chatName,
                sourceChatUsername: c.chatUsername,
                relatedID: c.msgUID
            ))
        }

        // Reply debt
        for debt in replyDebtItems {
            actions.append(DailyReportAction(
                content: "回复 \(debt.senderName): \(debt.preview.prefix(60))\(debt.preview.count > 60 ? "…" : "")",
                type: .replyDebt,
                urgency: urgencyForReplyDebt(debt),
                deadline: nil,
                sourceChatName: debt.chatName,
                sourceChatUsername: debt.chatUsername,
                relatedID: debt.chatUsername
            ))
        }

        // Pending asks
        for ask in pendingAsks {
            actions.append(DailyReportAction(
                content: ask.summary,
                type: .ask,
                urgency: urgencyFor(deadline: ask.deadlineAt),
                deadline: ask.deadlineAt,
                sourceChatName: ask.chatName,
                sourceChatUsername: ask.chatUsername,
                relatedID: ask.msgUID
            ))
        }

        // Sort by urgency ascending (critical first)
        actions.sort { $0.urgency < $1.urgency }

        // 8. Build risks
        var risks: [DailyReportRisk] = []

        for c in overdueCommitments {
            risks.append(DailyReportRisk(
                type: .overdueCommitment,
                description: "承诺「\(c.content)」已超期",
                severity: .high,
                sourceChatName: c.chatName,
                sourceChatUsername: c.chatUsername
            ))
        }

        for todo in runTodos where todo.deadline != nil && todo.deadline! < now {
            risks.append(DailyReportRisk(
                type: .overdueTodo,
                description: "待办「\(todo.content)」已超期",
                severity: .high,
                sourceChatName: todo.sourceChatName,
                sourceChatUsername: todo.sourceChatUsername
            ))
        }

        for r in todayRecalled where r.aiShouldNotify == true {
            let severity: RiskSeverity = (r.aiNotifyLevel == .strong) ? .high : .medium
            risks.append(DailyReportRisk(
                type: .recalledMessage,
                description: "\(r.senderName) 撤回了一条消息",
                severity: severity,
                sourceChatName: r.chatName,
                sourceChatUsername: r.chatUsername
            ))
        }

        for h in runHighlights where h.flaggedUncertain {
            risks.append(DailyReportRisk(
                type: .uncertainHighlight,
                description: "高亮信息置信度低: \(h.summary.prefix(50))",
                severity: .low,
                sourceChatName: h.sourceChatName,
                sourceChatUsername: h.sourceChatUsername
            ))
        }

        risks.sort { $0.severity < $1.severity }

        return DailyReport(
            date: now,
            dateRange: dateRange,
            generatedAt: now,
            metrics: metrics,
            highlights: highlights,
            actions: actions,
            risks: risks,
            pendingAsks: pendingAsks + handledAsks,
            narrative: nil,
            tomorrowFocus: nil,
            wechatDraft: nil
        )
    }

    // MARK: - Urgency helpers

    private func urgencyFor(deadline: Date?, status: CommitmentStatus? = nil) -> ActionUrgency {
        if let status = status, status == .overdue {
            return .critical
        }
        guard let deadline = deadline else { return .low }
        let now = Date()
        let diff = deadline.timeIntervalSince(now)
        if diff < 0 { return .critical }
        if diff < 86400 { return .high }
        if diff < 3 * 86400 { return .medium }
        return .low
    }

    private func urgencyForReplyDebt(_ debt: ReplyDebtItem) -> ActionUrgency {
        switch debt.priority {
        case .p0: return .critical
        case .p1: return .high
        case .p2: return .medium
        }
    }
}

import Foundation

// MARK: - Daily Report Data Model

/// A unified daily report that aggregates data from all available sources:
/// retrospective highlights, todos, pending asks, commitments, reply debt,
/// and recalled messages. Produced by `DailyReportBuilder`; consumed by
/// `AIDailyReportGenerator` for AI enrichment and by `DailyReportTabView`
/// for display.
struct DailyReport: Sendable {
    let date: Date
    let dateRange: (start: Date, end: Date)
    let generatedAt: Date

    let metrics: DailyReportMetrics
    let highlights: [DailyReportHighlight]
    let actions: [DailyReportAction]
    let risks: [DailyReportRisk]
    let pendingAsks: [PendingAsk]

    /// AI-generated fields (populated by AIDailyReportGenerator).
    var narrative: String?
    var tomorrowFocus: String?
    var wechatDraft: String?
}

// MARK: - Metrics

struct DailyReportMetrics: Sendable {
    let unreadMessageCount: Int
    let pendingTodoCount: Int
    let pendingAskCount: Int
    let pendingCommitmentCount: Int
    let overdueCommitmentCount: Int
    let replyDebtCount: Int
    let recalledMessageCount: Int
    let highlightCount: Int
    let analyzedChatCount: Int
}

// MARK: - Highlight

/// A highlight surfaced from the retrospective pipeline, enriched for
/// daily-report display.
struct DailyReportHighlight: Sendable {
    let summary: String
    let category: HighlightCategory
    let sourceChatName: String
    let sourceChatUsername: String
    let date: Date
    let confidence: Double
    let quotedSnippet: String?
    let involved: [String]
}

// MARK: - Action

/// A unified action item drawn from todos, commitments, or reply debt.
enum DailyReportActionType: String, Sendable {
    case todo, commitment, replyDebt, ask
}

struct DailyReportAction: Sendable {
    let content: String
    let type: DailyReportActionType
    let urgency: ActionUrgency
    let deadline: Date?
    let sourceChatName: String
    let sourceChatUsername: String
    let relatedID: String // todoID, commitment msgUID, or chatUsername
}

enum ActionUrgency: Int, Sendable, Comparable {
    case critical = 0   // overdue or red-banner
    case high = 1       // due today
    case medium = 2     // due within 3 days
    case low = 3        // no deadline or distant

    static func < (lhs: ActionUrgency, rhs: ActionUrgency) -> Bool {
        lhs.rawValue < rhs.rawValue
    }
}

// MARK: - Risk

struct DailyReportRisk: Sendable {
    let type: RiskType
    let description: String
    let severity: RiskSeverity
    let sourceChatName: String?
    let sourceChatUsername: String?
}

enum RiskType: String, Sendable {
    case overdueCommitment, overdueTodo, recalledMessage, uncertainHighlight, failedAnalysis
}

enum RiskSeverity: Int, Sendable, Comparable {
    case high = 0
    case medium = 1
    case low = 2

    static func < (lhs: RiskSeverity, rhs: RiskSeverity) -> Bool {
        lhs.rawValue < rhs.rawValue
    }
}

import Foundation

/// Generates AI-enriched narrative, tomorrow focus, and WeChat draft for a
/// daily report. Takes a `DailyReport` produced by `DailyReportBuilder`,
/// formats a context-rich prompt, calls the AI service, and returns the
/// report with `narrative`, `tomorrowFocus`, and `wechatDraft` populated.
///
/// Falls back to the original data-only report if AI fails or returns
/// unparseable output after retry.
actor AIDailyReportGenerator {
    private let aiService: AIService
    private let store: HUDStore
    private let promptLoader: PromptLoader
    private let promptVersion: String

    init(
        aiService: AIService,
        store: HUDStore,
        promptLoader: PromptLoader = PromptLoader(),
        promptVersion: String = "daily_report_v1"
    ) {
        self.aiService = aiService
        self.store = store
        self.promptLoader = promptLoader
        self.promptVersion = promptVersion
    }

    // MARK: - Output

    struct AIOutput: Decodable {
        let narrative: String
        let tomorrowFocus: String
        let wechatDraft: String

        enum CodingKeys: String, CodingKey {
            case narrative
            case tomorrowFocus = "tomorrow_focus"
            case wechatDraft = "wechat_draft"
        }
    }

    // MARK: - Generation

    /// Enriches a `DailyReport` with AI-generated fields. If AI fails,
    /// returns the original report unchanged.
    func enrich(_ report: DailyReport) async -> DailyReport {
        let started = Date()

        let template: String
        do {
            template = try promptLoader.load(version: promptVersion)
        } catch {
            await audit(report: report, output: "", latencyMs: 0, status: .parseError, error: "prompt load failed: \(error)", model: nil)
            return report
        }

        let userPrompt = formatPrompt(template: template, report: report)

        let first = await call(userPrompt)
        if let parsed = parse(first.text) {
            await audit(report: report, output: first.text, latencyMs: ms(since: started), status: .ok, error: nil, model: first.model)
            return report.withAI(
                narrative: parsed.narrative,
                tomorrowFocus: parsed.tomorrowFocus,
                wechatDraft: parsed.wechatDraft
            )
        }

        if first.text.isEmpty, let err = first.error {
            await audit(report: report, output: "", latencyMs: ms(since: started), status: .httpError, error: err, model: first.model)
            return report
        }

        let strict = userPrompt + "\n\n严格要求：上一次输出无法解析为 JSON。只输出符合 schema 的 JSON 对象，不要任何其他文字。"
        let second = await call(strict)
        if let parsed = parse(second.text) {
            await audit(report: report, output: second.text, latencyMs: ms(since: started), status: .ok, error: "recovered after retry", model: second.model)
            return report.withAI(
                narrative: parsed.narrative,
                tomorrowFocus: parsed.tomorrowFocus,
                wechatDraft: parsed.wechatDraft
            )
        }

        await audit(report: report, output: second.text, latencyMs: ms(since: started), status: .parseError, error: second.error ?? "JSON parse failed after retry", model: second.model)
        return report
    }

    // MARK: - Prompt formatting

    /// Formats the prompt template with report data. Caps highlights,
    /// actions, and risks to respect token budgets.
    nonisolated func formatPrompt(template: String, report: DailyReport) -> String {
        let metrics = report.metrics

        let highlightsText = report.highlights.prefix(8).enumerated().map { (i, h) in
            let snippet = h.quotedSnippet.map { " \"\($0.prefix(40))\($0.count > 40 ? "…" : "")\"" } ?? ""
            return "\(i + 1). [\(h.sourceChatName)] \(h.summary.prefix(60))\(h.summary.count > 60 ? "…" : "")\(snippet)"
        }.joined(separator: "\n")

        let actionsText = report.actions.prefix(12).enumerated().map { (i, a) in
            let deadlineStr = a.deadline.map { " (截止: \($0.formatted(date: .abbreviated, time: .shortened))" } ?? ""
            let typeLabel = typeLabel(a.type)
            return "\(i + 1). [\(typeLabel)][\(a.sourceChatName)] \(a.content.prefix(60))\(a.content.count > 60 ? "…" : "")\(deadlineStr)"
        }.joined(separator: "\n")

        let risksText = report.risks.prefix(5).enumerated().map { (i, r) in
            let source = r.sourceChatName.map { " [\($0)]" } ?? ""
            return "\(i + 1).\(source) \(r.description)"
        }.joined(separator: "\n")

        return template
            .replacingOccurrences(of: "{unread_count}", with: "\(metrics.unreadMessageCount)")
            .replacingOccurrences(of: "{analyzed_chat_count}", with: "\(metrics.analyzedChatCount)")
            .replacingOccurrences(of: "{highlight_count}", with: "\(metrics.highlightCount)")
            .replacingOccurrences(of: "{pending_todo_count}", with: "\(metrics.pendingTodoCount)")
            .replacingOccurrences(of: "{pending_ask_count}", with: "\(metrics.pendingAskCount)")
            .replacingOccurrences(of: "{pending_commitment_count}", with: "\(metrics.pendingCommitmentCount)")
            .replacingOccurrences(of: "{overdue_commitment_count}", with: "\(metrics.overdueCommitmentCount)")
            .replacingOccurrences(of: "{reply_debt_count}", with: "\(metrics.replyDebtCount)")
            .replacingOccurrences(of: "{recalled_count}", with: "\(metrics.recalledMessageCount)")
            .replacingOccurrences(of: "{highlights}", with: highlightsText.isEmpty ? "暂无高亮数据" : highlightsText)
            .replacingOccurrences(of: "{actions}", with: actionsText.isEmpty ? "暂无待办" : actionsText)
            .replacingOccurrences(of: "{risks}", with: risksText.isEmpty ? "暂无风险" : risksText)
    }

    nonisolated private func typeLabel(_ type: DailyReportActionType) -> String {
        switch type {
        case .todo: return "待办"
        case .commitment: return "承诺"
        case .replyDebt: return "回复"
        case .ask: return "请求"
        }
    }

    // MARK: - Model call

    private struct ModelResponse {
        let text: String
        let error: String?
        let model: String?
    }

    private func call(_ userPrompt: String) async -> ModelResponse {
        let trackID = "daily:\(UUID().uuidString.prefix(8))"
        AIActivityTracker.shared.begin(trackID, label: "日报生成")
        defer { AIActivityTracker.shared.end(trackID) }

        do {
            let result = try await aiService.completeWithMetadata(
                system: "你是一个工作日汇总助手，严格按要求输出 JSON。",
                user: userPrompt,
                options: CompleteOptions(timeout: 90, temperature: 0.2, maxTokens: 1024, responseFormatJSON: true)
            )
            return ModelResponse(text: result.text, error: nil, model: result.model)
        } catch {
            return ModelResponse(text: "", error: error.localizedDescription, model: nil)
        }
    }

    // MARK: - Parsing

    // internal for testing
    nonisolated func parse(_ raw: String) -> AIOutput? {
        AIJSONExtractor.decodeFirstObject(from: raw, as: AIOutput.self)
    }

    // MARK: - Audit

    private func audit(report: DailyReport, output: String, latencyMs: Int, status: AIAuditStatus, error: String?, model actualModel: String?) async {
        let model: String
        if let actualModel {
            model = actualModel
        } else {
            model = await aiService.currentConfig().model
        }
        let entry = AIAuditEntry(
            id: 0,
            ts: Date(),
            role: .retrospector,
            model: model,
            promptVersion: promptVersion,
            inputText: "[daily_report|\(report.dateRange.start.formatted(date: .abbreviated, time: .omitted))|highlights=\(report.highlights.count)|actions=\(report.actions.count)|risks=\(report.risks.count)]",
            outputText: output,
            latencyMs: latencyMs,
            status: status,
            errorMessage: error
        )
        do {
            try store.writeAIAudit(entry)
        } catch {
            print("[WCHUD] AIDailyReportGenerator: failed to write audit: \(error)")
        }
    }

    // MARK: - Helpers

    private func ms(since start: Date) -> Int {
        Int(Date().timeIntervalSince(start) * 1000)
    }
}

// MARK: - DailyReport extension

