            recalledMessageCount: 0,
            highlightCount: 2,
            analyzedChatCount: 10
        )

        let report = DailyReport(
            date: now,
            dateRange: (start: now, end: now),
            generatedAt: now,
            metrics: metrics,
            highlights: [],
            actions: [],
            risks: [],
            pendingAsks: [],
